import{_ as t,c as a,o as i,ag as r}from"./chunks/framework.ARG558ZT.js";const u=JSON.parse('{"title":"Verification, gaps and limits","description":"","frontmatter":{},"headers":[],"relativePath":"learner-guide/verification.md","filePath":"learner-guide/verification.md"}'),n={name:"learner-guide/verification.md"};function s(o,e,d,c,l,p){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="verification-gaps-and-limits" tabindex="-1">Verification, gaps and limits <a class="header-anchor" href="#verification-gaps-and-limits" aria-label="Permalink to “Verification, gaps and limits”">​</a></h1><p><a href="./">Guide home</a> · <a href="./ui.html">Screenshots and captions</a> · <a href="./../review/verification.html">Current reference verification</a></p><h2 id="scope-and-provenance" tabindex="-1">Scope and provenance <a class="header-anchor" href="#scope-and-provenance" aria-label="Permalink to “Scope and provenance”">​</a></h2><p>Prepared 2026-10-28 against the current files, navigation configuration and locally rendered application. Sources included <code>CURRENT_LEARNING_SUMMARY.md</code>, the current progress ledger and historical round-two audit, the complete <code>ROUND_2_INVENTORY.json</code>, current track indexes/coverage maps, workbench boundaries and staged/shared practice specifications. Historical reports remain historical; no curriculum expansion or new homework implementation is introduced.</p><p>The two mapping pages account for <strong>302 substantive textbook/reading-guide entries + 775 supporting entries = all 1,077 baseline inventory files</strong>. The baseline is dated 2026-10-27; new guide pages/screenshots are later additions, not silently inserted into that preserved inventory. Each substantive row retains its source title, practice mapping and material scope. Supporting rows retain exact paths, roles and teaching owners. Mapping accounts for existence and placement, not a new correctness review of every implementation.</p><h2 id="exact-gaps-and-ambiguities-discovered" tabindex="-1">Exact gaps and ambiguities discovered <a class="header-anchor" href="#exact-gaps-and-ambiguities-discovered" aria-label="Permalink to “Exact gaps and ambiguities discovered”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Exact location / impact</th><th>Treatment</th></tr></thead><tbody><tr><td>Menu order differs from study order</td><td><code>docs/.vitepress/config.mjs</code>: frontend/CS precede Node; numbered module history and P-331-first project layout can imply the wrong starting route</td><td>Explicit Node quick start and roadmap; no menu redesign</td></tr><tr><td>Inventory practice links vary in specificity</td><td><code>ROUND_2_INVENTORY.json</code>: 306 entries say only <code>outstanding</code>, including practice/fixtures; broad lesson mappings often name a parent project</td><td>Exact support crosswalk plus track/stage tables; matching focused specifications linked where present; broad mapping is not a new per-file dependency claim</td></tr><tr><td>New orientation outside historical inventory</td><td>This <code>docs/learner-guide/</code> tree was created after the baseline</td><td>Separate later addition, preserved baseline counts/hashes untouched</td></tr><tr><td>Specialist depth is deliberately bounded</td><td><code>docs/engineering/design.md</code>, <code>docs/python-for-ai/index.md</code>, coverage maps</td><td>Optional-after-primary placements; no claim of a complete cloud/cluster/graph-training curriculum</td></tr><tr><td>External contents unknown</td><td><code>docs/materials.md</code>, <code>docs/assessment.md</code>, <code>docs/knowledge_testing.md</code></td><td>External-resource role retained; linked course contents not fetched/certified</td></tr><tr><td>No learner completion evidence</td><td>All N/F/CS/E/P/RAG/WF/N8N practice</td><td>Outstanding by default; separate progress template</td></tr></tbody></table><p>No missing essential practice specification was identified in the inspected staged paths. Matching chapter assignments and shared projects are reused. This is not proof that every specification has an explicit machine-readable dependency edge: where sources give capability prerequisites rather than assignment IDs, the track page labels a recommended sequence and does not invent a hard dependency. The inventory is a file crosswalk, not an executable prerequisite graph.</p><h2 id="checks-performed-for-this-guide" tabindex="-1">Checks performed for this guide <a class="header-anchor" href="#checks-performed-for-this-guide" aria-label="Permalink to “Checks performed for this guide”">​</a></h2><ul><li><code>npm run docs:build -- --outDir /tmp/learner-guide-site</code>: passed after creating the verification page and correcting the analyzer N-01 anchor (its actual generated ID contains an em dash). The existing large-chunk advisory remains.</li><li>Built HTML validation covered all nine guide pages plus Home and Hub map, checking local destinations, image paths and fragment IDs. Exact totals/results are retained in <a href="/learner-guide/evidence/link-results.json">link results</a>.</li><li>Baseline mapping reconciliation: 302 substantive rows and 775 supporting rows, 1,077 distinct inventory paths. No baseline entry omitted. This is baseline coverage, not a new count of skills.</li><li>Chrome navigation: captured Home, Hub map, Node overview, streams lesson, workbench and analyzer practice; clicked Learning paths, mobile global navigation open/close, mobile topic Menu and On this page. Clicked the streams article&#39;s Backpressure contents link and observed <code>#_9-backpressure</code>. Other destination pages were opened directly rather than claiming an end-to-end click through every link.</li><li>Seven guide pages inspected in Chrome at 1440 × 1000; quick start, roadmap, topics, support and walkthrough additionally checked at 390 × 844. No document-width overflow observed on those pages. The exact measurements are retained in <a href="/learner-guide/evidence/browser-results.json">browser results</a>. The initial diagram-specific selector matched no elements; a follow-up confirmed <strong>two article SVGs</strong>, captured them separately and inspected both visually.</li><li>All nine initial application screenshots, both diagram captures and the mobile outline capture were visually inspected. Desktop text/menu states are readable. The drawer capture intentionally clips a long scrollable course list. Diagram labels shrink on narrow screens; full-size image links and prose/table alternatives are provided. Browser image zoom itself was not interaction-tested.</li><li>Scoped whitespace checks passed. Production code, package scripts, dependency locks, restricted tests and historical assessments were not edited. Existing author runtime/database/model checks were not rerun or credited as learner practice.</li></ul><p>The root package defines <code>docs:build</code> rather than <code>build</code>, <code>test</code> or <code>coverage</code>. This task changes documentation only, so Autocode submission build/Jest/Module 4 coverage are not applicable to this repository change. The learner guide preserves those requirements for future submitted implementations.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to “Limits”">​</a></h2><p>No screen-reader, keyboard accessibility audit, zoom, physical mobile device, cross-engine, live provider, n8n installation/publication, cloud deployment, paid activation or production traffic check is claimed. Responsive captures use the same installed Chrome engine at two viewport sizes. No homework solution, <code>src/tests</code> change, dependency/configuration change, remote push or published workflow is part of this work. Existing generated <code>dist</code> changes are preserved; the new build uses a temporary output directory.</p>',13)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
